 db.prepare=q=>{queries.push(q);return prepare(q);};const put=n=>{const bytes=f.video.subarray(n*PART,(n+1)*PART);return api.putSiteArchivePart(ID,{site_archive_id:sid,part:n,chunk_base64:bytes.toString('base64'),chunk_sha256:sha(bytes)},actor);};
